import { MikroORM } from "@mikro-orm/postgresql";
import config from "server/database/mikro-orm.config";
import { globalValues } from "server/express/global";
import { App_User_db, Doc_Listing_db } from "server/database/models/_allModels";
import { asNobody, asUser, upsertAppUser, grantMissionPerms } from "../../fixtures/access";
import DocListingFactory from "../../fixtures/entityFactories/DocListingFactory";
import supertest from "supertest";
import app from "server/express/restApi";
import { createMockAutomergeRepo } from "../../helpers/mockAutomergeRepo";
import { generateBlankEVA } from "store/storeUtils/eva";
import { generateBlankRex } from "store/storeUtils/rex";
import { generateBlankStation } from "store/storeUtils/station";
import { generateBlankTraverse } from "store/storeUtils/traverse";

let testAppUser: App_User_db;
const VIEW_UUPIC = "vitest-dust-view";
const NO_PERMS_UUPIC = "vitest-dust-noperms";
let testAutomergeDocListings: Doc_Listing_db[];
let testMissionsPartial: Partial<Mission>[];

// EVA / traverse / rex data that the tests will inspect
let eva: Eva;
let rexEva: Eva;
let rex: Rex;
let stationA: Station;
let stationB: Station;
let stationC: Station;
let traverseAB: Traverse;
let traverseBC: Traverse;

beforeAll(async () => {
  globalValues.orm = await MikroORM.init(config);
  const em = globalValues.orm.em.fork();

  // Allocate a real DB Doc_Listing to get autogenerated mission IDs
  testAutomergeDocListings = await new DocListingFactory(em)
    .each((record, index) => {
      record.automergeUrl = `automerge:VitestDustMission${index + 1}`;
    })
    .create(2);

  // Three stations at distinct locations: A → B → C
  stationA = generateBlankStation({ name: "Station A", location: { lat: 10.0, lng: 20.0 } });
  stationB = generateBlankStation({ name: "Station B", location: { lat: 11.0, lng: 21.0 } });
  stationC = generateBlankStation({ name: "Station C", location: { lat: 12.0, lng: 22.0 } });

  // Traverse A→B ends at the same point that traverse B→C starts — that
  // shared point (B) must be de-duped when the route builds the full path.
  traverseAB = generateBlankTraverse({
    path: [
      { lat: 10.0, lng: 20.0 }, // station A
      { lat: 10.5, lng: 20.5 }, // mid-point
      { lat: 11.0, lng: 21.0 }, // station B (shared with traverseBC start)
    ],
  });
  traverseBC = generateBlankTraverse({
    path: [
      { lat: 11.0, lng: 21.0 }, // station B – duplicate of traverseAB last point
      { lat: 11.5, lng: 21.5 }, // mid-point
      { lat: 12.0, lng: 22.0 }, // station C
    ],
  });

  // Realistic EVA sequence: station → traverse → station → traverse → station
  eva = generateBlankEVA({
    name: "Vitest Dust EVA",
    datetime: new Date("2025-01-15T10:00:00Z").getTime(),
    sequence: [
      { type: "station", uuid: stationA.uuid },
      { type: "traverse", uuid: traverseAB.uuid },
      { type: "station", uuid: stationB.uuid },
      { type: "traverse", uuid: traverseBC.uuid },
      { type: "station", uuid: stationC.uuid },
    ],
  });

  // A rex-EVA paired with a rex
  rexEva = generateBlankEVA({
    name: "Vitest Dust Rex EVA",
    refUuid: eva.refUuid,
    sequence: [],
  });
  rex = generateBlankRex({ name: "Vitest Dust Rex", evaUuid: rexEva.uuid });

  testMissionsPartial = [
    // Mission 0: has EVAs, traverses, and a rex
    {
      id: testAutomergeDocListings[0].missionId,
      name: "Vitest Dust Mission 1",
      archivedAt: null,
      evas: {
        [eva.uuid]: eva,
        [rexEva.uuid]: rexEva,
      },
      traverses: {
        [traverseAB.uuid]: traverseAB,
        [traverseBC.uuid]: traverseBC,
      },
      rexes: {
        [rex.uuid]: rex,
      },
    },
    // Mission 1: no EVAs / traverses
    {
      id: testAutomergeDocListings[1].missionId,
      name: "Vitest Dust Mission 2",
      archivedAt: null,
      evas: {},
      traverses: {},
      rexes: {},
    },
  ];

  globalValues.automergeRepo = createMockAutomergeRepo(testMissionsPartial);

  // A user with view access to mission 0 only
  testAppUser = await upsertAppUser(em, VIEW_UUPIC);
  await grantMissionPerms(em, {
    missionId: testMissionsPartial[0].id,
    userId: testAppUser.id,
    permLevel: "viewer",
  });

  // An identity with no grants at all
  await upsertAppUser(em, NO_PERMS_UUPIC);
});

describe("GET /api/v1/external/dust", () => {
  describe("Authentication", () => {
    test("Returns 401 when not logged in and no missionId provided", async () => {
      const res = await supertest(app).get("/api/v1/external/dust").set(asNobody());
      expect(res.statusCode).toBe(401);
      expect(res.body.status).toBe("failure");
      expect(res.body.message).toBe("Unauthorized");
    });

    test("Returns 401 when logged-in user has no permissions for the mission", async () => {
      const res = await supertest(app)
        .get("/api/v1/external/dust")
        .set(asUser(NO_PERMS_UUPIC))
        .query({ missionId: testMissionsPartial[0].id });
      expect(res.statusCode).toBe(401);
      expect(res.body.status).toBe("failure");
      expect(res.body.message).toBe("Unauthorized");
    });
  });

  describe("Validation", () => {
    const emssToken = process.env.EMSS_TOKEN;

    test("Returns 400 when missionId is missing", async () => {
      const res = await supertest(app).get("/api/v1/external/dust").set("emss-token", emssToken);
      expect(res.statusCode).toBe(400);
      expect(res.body.status).toBe("error");
      expect(res.body.message).toContain("Invalid mission ID");
    });

    test("Returns 400 when missionId is not a number", async () => {
      const res = await supertest(app)
        .get("/api/v1/external/dust")
        .set("emss-token", emssToken)
        .query({ missionId: "not-a-number" });
      expect(res.statusCode).toBe(400);
      expect(res.body.status).toBe("error");
      expect(res.body.message).toContain("Invalid mission ID");
    });
  });

  describe("Dust data", () => {
    test("Returns 200 with correct top-level shape for a mission with EVAs", async () => {
      const res = await supertest(app)
        .get("/api/v1/external/dust")
        .set(asUser(VIEW_UUPIC))
        .query({ missionId: testMissionsPartial[0].id });

      expect(res.statusCode).toBe(200);
      expect(res.body.status).toBe("success");
      expect(res.body.message).toBe("data successfully retrieved");

      const data = res.body.data;
      expect(data.missionId).toBe(testMissionsPartial[0].id);
      expect(data.name).toBe("Vitest Dust Mission 1");
      expect(data.traversesGeoJson).toBeDefined();
    });

    test("Includes an entry for each EVA (planned + rex EVA)", async () => {
      const res = await supertest(app)
        .get("/api/v1/external/dust")
        .set(asUser(VIEW_UUPIC))
        .query({ missionId: testMissionsPartial[0].id });

      const { traversesGeoJson } = res.body.data;
      expect(Object.keys(traversesGeoJson)).toHaveLength(2);
      expect(traversesGeoJson[eva.uuid]).toBeDefined();
      expect(traversesGeoJson[rexEva.uuid]).toBeDefined();
    });

    test("As-planned EVA has correct name, null rexUuid and rexName", async () => {
      const res = await supertest(app)
        .get("/api/v1/external/dust")
        .set(asUser(VIEW_UUPIC))
        .query({ missionId: testMissionsPartial[0].id });

      const evaEntry = res.body.data.traversesGeoJson[eva.uuid];
      expect(evaEntry.evaName).toBe("Vitest Dust EVA");
      expect(evaEntry.rexUuid).toBeNull();
      expect(evaEntry.rexName).toBeNull();
    });

    test("Rex EVA entry has rexUuid and rexName populated", async () => {
      const res = await supertest(app)
        .get("/api/v1/external/dust")
        .set(asUser(VIEW_UUPIC))
        .query({ missionId: testMissionsPartial[0].id });

      const rexEvaEntry = res.body.data.traversesGeoJson[rexEva.uuid];
      expect(rexEvaEntry.rexUuid).toBe(rex.uuid);
      expect(rexEvaEntry.rexName).toBe(rex.name);
    });

    test("Full traverse GeoJSON is a valid FeatureCollection with a LineString", async () => {
      const res = await supertest(app)
        .get("/api/v1/external/dust")
        .set(asUser(VIEW_UUPIC))
        .query({ missionId: testMissionsPartial[0].id });

      const evaEntry = res.body.data.traversesGeoJson[eva.uuid];
      const fc = evaEntry.fullTraverse;
      expect(fc.type).toBe("FeatureCollection");
      expect(fc.features).toHaveLength(1);
      const feature = fc.features[0];
      expect(feature.type).toBe("Feature");
      expect(feature.geometry.type).toBe("LineString");
    });

    test("Duplicate consecutive coordinates are de-duped in the LineString", async () => {
      const res = await supertest(app)
        .get("/api/v1/external/dust")
        .set(asUser(VIEW_UUPIC))
        .query({ missionId: testMissionsPartial[0].id });

      const evaEntry = res.body.data.traversesGeoJson[eva.uuid];
      const coords = evaEntry.fullTraverse.features[0].geometry.coordinates;
      expect(coords).toHaveLength(5);
      expect(coords[0]).toEqual([20.0, 10.0]); // station A
      expect(coords[1]).toEqual([20.5, 10.5]); // mid A→B
      expect(coords[2]).toEqual([21.0, 11.0]); // station B (kept once/de-duped)
      expect(coords[3]).toEqual([21.5, 11.5]); // mid B→C
      expect(coords[4]).toEqual([22.0, 12.0]); // station C
    });

    test("start_datetime is an ISO string matching EVA datetime", async () => {
      const res = await supertest(app)
        .get("/api/v1/external/dust")
        .set(asUser(VIEW_UUPIC))
        .query({ missionId: testMissionsPartial[0].id });

      const evaEntry = res.body.data.traversesGeoJson[eva.uuid];
      expect(evaEntry.fullTraverse.start_datetime).toBe("2025-01-15T10:00:00.000Z");
    });

    test("EVA with no traverses in sequence yields an empty LineString", async () => {
      const res = await supertest(app)
        .get("/api/v1/external/dust")
        .set(asUser(VIEW_UUPIC))
        .query({ missionId: testMissionsPartial[0].id });

      // rexEva has an empty sequence
      const rexEvaEntry = res.body.data.traversesGeoJson[rexEva.uuid];
      const coords = rexEvaEntry.fullTraverse.features[0].geometry.coordinates;
      expect(coords).toHaveLength(0);
    });

    test("Mission with no EVAs returns empty traversesGeoJson", async () => {
      // Use emss-token for blanket access since testAppUser only has permission
      // for mission 0, not mission 1.
      const res = await supertest(app)
        .get("/api/v1/external/dust")
        .set("emss-token", process.env.EMSS_TOKEN)
        .query({ missionId: testMissionsPartial[1].id });

      expect(res.statusCode).toBe(200);
      expect(res.body.status).toBe("success");
      expect(res.body.data.traversesGeoJson).toEqual({});
    });
  });
});

afterAll(async () => {
  const em = globalValues.orm.em.fork();
  for (const listing of testAutomergeDocListings) {
    await em.nativeDelete(Doc_Listing_db, { missionId: listing.missionId });
  }
  await em.nativeDelete(App_User_db, { id: testAppUser.id });
  await em.nativeDelete(App_User_db, { uupic: NO_PERMS_UUPIC });
  await globalValues.orm.close();
  globalValues.orm = null;
  vi.restoreAllMocks();
});
